import{_ as e,o,c as a,ag as s}from"./chunks/framework.Cyu1VozZ.js";const g=JSON.parse('{"title":"Themes & Layouts","description":"","frontmatter":{},"headers":[],"relativePath":"slides/themes-and-layouts.md","filePath":"slides/themes-and-layouts.md"}'),n={name:"slides/themes-and-layouts.md"};function i(r,t,l,h,d,c){return o(),a("div",null,[...t[0]||(t[0]=[s('<h1 id="themes-layouts" tabindex="-1">Themes &amp; Layouts <a class="header-anchor" href="#themes-layouts" aria-label="Permalink to &quot;Themes &amp; Layouts&quot;">​</a></h1><p>Themes and layouts let you set the visual style of a deck once and reuse it across every slide.</p><h2 id="what-is-a-theme" tabindex="-1">What is a Theme? <a class="header-anchor" href="#what-is-a-theme" aria-label="Permalink to &quot;What is a Theme?&quot;">​</a></h2><p>A <strong>theme</strong> bundles the colors, fonts, and background used across a deck. Switching themes reskins the whole deck in one click — your content (text, images, shapes) stays put, only the visual treatment changes.</p><p>Each theme defines:</p><ul><li>A <strong>color scheme</strong> with theme roles (background, text, accent, etc.). Shapes and text bound to a theme role automatically update when you switch themes.</li><li>A <strong>font scheme</strong> for headings and body text. Text inside placeholders picks up the theme&#39;s heading or body font automatically.</li><li>A <strong>background</strong> style applied to every slide.</li></ul><h2 id="built-in-themes" tabindex="-1">Built-in Themes <a class="header-anchor" href="#built-in-themes" aria-label="Permalink to &quot;Built-in Themes&quot;">​</a></h2><p>Wafflebase ships with <strong>23 built-in themes</strong> covering neutral, light, editorial, vibrant, and dark looks. Click the palette button in the toolbar (tooltip: <strong>Theme</strong>) to open the Theme panel on the right, then click a thumbnail to apply it.</p><ul><li><strong>Simple Light</strong> and <strong>Simple Dark</strong> — neutral baselines</li><li>Streamline, Swiss, Paradigm, Material, Shift, Momentum, Focus, Luxe, Modern Writer, Coral, Spearmint, Pop, Tropic, Marina, Geometric, Plum, Slate, Forest, Spotlight, Beach Day</li><li><strong>Wafflebase</strong> — the Wafflebase brand palette</li></ul><p>A new deck is seeded with <strong>Simple Light</strong>, or with <strong>Simple Dark</strong> if the app is in dark mode when you create it. You can switch themes at any time.</p><p>Each entry in the picker is a swatch card, not a preview of your slides: it shows an <code>aA</code> type sample on the theme&#39;s background, a strip of its six accent colors, and the theme&#39;s name.</p><h2 id="customizing-a-theme" tabindex="-1">Customizing a Theme <a class="header-anchor" href="#customizing-a-theme" aria-label="Permalink to &quot;Customizing a Theme&quot;">​</a></h2><p>The <strong>Theme</strong> panel has two tabs: <strong>themes</strong> picks one from the catalog, <strong>customize</strong> edits the one the deck is currently using. Every change applies to the whole deck immediately and counts as a single undo step.</p><p>The customize tab has four sections:</p><ul><li><strong>Colors</strong> — the twelve theme color roles: Text, Background, Text 2, Background 2, Accent 1–6, Link, and Visited link. Anything on a slide bound to a role follows the change; anything you gave a literal hex color does not.</li><li><strong>Fonts</strong> — the <strong>Headings</strong> and <strong>Body</strong> fonts.</li><li><strong>Background</strong> — the master background fill, which is what slides that haven&#39;t set their own background use. If you&#39;ve changed it, a <strong>Match theme</strong> button appears to put it back.</li><li><strong>Layouts</strong> — <strong>Edit layout positions</strong> switches the canvas into layout-editing mode, where you drag a layout&#39;s placeholders. Changes flow to every slide using that layout.</li></ul><p>Once you&#39;ve edited a built-in theme, the panel shows the modified theme under <strong>In this presentation</strong> at the top of the themes tab, and a <strong>Reset to original</strong> button appears in the customize tab to discard your changes.</p><h2 id="layouts" tabindex="-1">Layouts <a class="header-anchor" href="#layouts" aria-label="Permalink to &quot;Layouts&quot;">​</a></h2><p>A <strong>layout</strong> is a pre-arranged template for a slide — for example, &quot;Title slide&quot; or &quot;Title and body&quot;. Each layout defines a set of <strong>placeholders</strong> that you fill in with your content.</p><p>There are eleven built-in layouts, matching Google Slides. They are listed here in the order they appear in the layout picker:</p><table tabindex="0"><thead><tr><th>Layout</th><th>Use it for</th></tr></thead><tbody><tr><td>Blank</td><td>Empty canvas, no placeholders</td></tr><tr><td>Title slide</td><td>The opening slide of a deck — large title + subtitle</td></tr><tr><td>Section header</td><td>Section dividers between groups of slides</td></tr><tr><td>Title and body</td><td>A title with a single body region (text, bullets, or content)</td></tr><tr><td>Title and two columns</td><td>A title above two side-by-side content regions</td></tr><tr><td>Title only</td><td>A title with the rest of the slide left blank</td></tr><tr><td>One column text</td><td>A full-width body region for prose-heavy slides</td></tr><tr><td>Main point</td><td>A single large takeaway, centered</td></tr><tr><td>Section title and description</td><td>A section title plus a paragraph of description</td></tr><tr><td>Caption</td><td>A large image area with a caption below</td></tr><tr><td>Big number</td><td>A single large numeric stat as the focal point</td></tr></tbody></table><h2 id="choosing-a-layout" tabindex="-1">Choosing a Layout <a class="header-anchor" href="#choosing-a-layout" aria-label="Permalink to &quot;Choosing a Layout&quot;">​</a></h2><p>There are two separate actions, and it&#39;s worth keeping them apart:</p><p><strong>To add a <em>new</em> slide with a chosen layout</strong>, use the <strong>Add slide</strong> control in the toolbar. Clicking the button itself adds a blank slide; clicking the chevron next to it opens <strong>Choose a layout</strong>, and picking one inserts a new slide with that layout after the current one. This control never changes the slide you are looking at.</p><p><strong>To re-lay-out the slide you are already on</strong>, right-click it — either on an empty part of the canvas or on its thumbnail in the strip — and choose <strong>Change layout…</strong>, then pick the new layout. There is no toolbar button for this.</p><p>When you change layout, the slide&#39;s existing placeholders are matched to the new layout&#39;s slots when their types align, so the title stays a title and the body stays a body.</p><h2 id="slide-backgrounds" tabindex="-1">Slide Backgrounds <a class="header-anchor" href="#slide-backgrounds" aria-label="Permalink to &quot;Slide Backgrounds&quot;">​</a></h2><p>A theme sets the background for the whole deck. To override it on one slide, click the background button in the toolbar (tooltip: <strong>Background</strong>) to open the Background panel.</p><p><strong>Color</strong> offers two tabs. <strong>Solid</strong> is a color picker with the theme palette, standard colors, a custom color, and a transparency slider. <strong>Gradient</strong> gives you a stops bar — click to add a stop, drag to move it, and set each stop&#39;s color — plus eight direction presets and an angle. Gradients here are linear.</p><p><strong>Image</strong> lets you pick a picture as the background, then set its <strong>Opacity</strong>, swap it with <strong>Replace image…</strong>, or take it away with <strong>Remove image</strong>. A slide&#39;s <em>own</em> background is either a color or an image, not both — setting one here clears the other.</p><p>Two actions sit at the bottom:</p><ul><li><strong>Reset to theme</strong> drops this slide&#39;s own background so it inherits from the theme again.</li><li><strong>Apply to all slides</strong> pushes this slide&#39;s background onto the deck&#39;s master, so it becomes the new baseline. Slides that have set their <em>own</em> background keep it. The master is the one place the either/or above doesn&#39;t apply: it always takes the color, and takes the image too when the current slide shows one — inheriting slides then paint that image over the color.</li></ul><p>The panel always edits the slide you&#39;re currently on, and follows you as you move between slides.</p><h2 id="placeholders" tabindex="-1">Placeholders <a class="header-anchor" href="#placeholders" aria-label="Permalink to &quot;Placeholders&quot;">​</a></h2><p>A <strong>placeholder</strong> is a typed content slot in a layout — a title, a body, an image area, a footer. Placeholders carry the layout&#39;s default formatting (font, size, alignment) so text added through them automatically matches the theme.</p><p>When you switch layouts, Wafflebase preserves placeholder identity where possible: a title placeholder remains a title even if the new layout positions it differently, so its content survives the change.</p><h2 id="what-s-next" tabindex="-1">What&#39;s Next <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s Next&quot;">​</a></h2><ul><li><a href="./build-a-deck.html">Build a Deck</a> — End-to-end tutorial</li><li><a href="./keyboard-shortcuts.html">Keyboard Shortcuts</a> — Slide, selection, and formatting shortcuts</li></ul>',37)])])}const p=e(n,[["render",i]]);export{g as __pageData,p as default};
